mapper.select:
        select a.ftp_income_id, sum(a.ftp_income) as ftp_income from ftp_income_detail_record a
        
            
                AND a.interest_date >= #{from}
            
            
                AND #{to} >= a.interest_date
            

            
                AND a.ftp_income_id IN
                
                    #{item}
                
            
        
         group by a.ftp_income_id
